import { describe, expect, it } from "vitest";
import { quote } from "./claim-office.js";

describe("MHPCO claim office", () => {
  // --- Base premiums per item type (price list) ---
  it("quotes an empty item list as premium 5 G (processing fee only)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [])).toBe(5);
  });
  it("quotes a single plain sword at base 100 G -> premium 115 G (100 + 10 first insurance + 5 fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
  });
  it("quotes a single plain amulet at base 60 G -> premium 71 G (60 + 6 first insurance + 5 fee)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }])).toBe(71);
  });
  it.todo("quotes a single plain staff at base 80 G -> premium 93 G (80 + 8 first insurance + 5 fee)");
  it.todo("quotes a single plain potion at base 40 G -> premium 49 G (40 + 4 first insurance + 5 fee)");
  it.todo("quotes a single rune component at base 25 G -> premium 33 G (25 + 2.5 first insurance = 27.5 -> 5 fee -> 32.5 rounded up to 33)");
  it.todo("quotes a single moonstone component at base 25 G -> premium 33 G");

  // --- Building block of 3 alike components ---
  it.todo("quotes 2 runes as base premium 50 G (no block)");
  it.todo("quotes 3 runes as base premium 60 G (block applies)");
  it.todo("quotes 4 runes as base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes as base premium 175 G (no block -- block requires exactly 3)");

  // --- "Alike" components means exactly the same type ---
  it.todo("quotes 2 runes + 1 moonstone as base premium 75 G (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks of alike types)");

  // --- Item-specific modifiers ---
  it.todo("adds a 50% curse surcharge to a cursed item's base premium (cursed sword: 100 + 50)");
  it.todo("adds a 30% high-enchantment surcharge for enchantment 5 (sword: 100 + 30)");
  it.todo("adds no high-enchantment surcharge for enchantment 4 (sword: base 100 only)");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 (100 + 50 + 30)");

  // --- Modifier scope on multi-item policies ---
  it.todo("applies the curse surcharge only to the cursed item's base premium: cursed sword + plain amulet -> 160 base + 50 curse = 210 G before policy modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("applies a 20% loyalty discount for a customer with exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
  it.todo("applies a 10% first-insurance surcharge on the policy base premium of every quote");
  it.todo("applies a 15% follow-up discount on each contract after the customer's first quote in the scenario");
  it.todo("adds the 5 G processing fee at the very end of every premium");

  // --- Rounding in MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G");
  it.todo("rounds a payout of 350.5 G down to 350 G");

  // --- Integration premium examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) as premium 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) as premium 160 G");

  // --- Insurance sum and cap ---
  it.todo("reports a policy covering a sword and an amulet as insurance sum 1600 G with cap 3200 G");
  it.todo("reports a policy covering two swords as insurance sum 2000 G with cap 4000 G");
  it.todo("bases the cap on unmodified insurance values: cursed sword (premium 165 G) still has cap 2000 G");
  it.todo("reports a policy covering a sword and 3 runes as insurance sum 1750 G (block discount affects premium only), cap 3500 G");

  // --- Standard claim reimbursement and deductible ---
