export interface Customer {
  readonly yearsWithMHPCO: number;
}

export interface Item {
  readonly type: string;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUM_PRICE_LIST: Readonly<Record<string, number>> = {
  sword: 100,
  amulet: 60,
};

function basePremiumOf(item: Item): number {
  return BASE_PREMIUM_PRICE_LIST[item.type] ?? 0;
}

function policyWideSurchargeOn(policyBasePremium: number): number {
  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
}

function roundInOfficesFavour(premium: number): number {
  return Math.ceil(premium);
}

export function quote(customer: Customer, items: readonly Item[]): number {
  const policyBasePremium = items.reduce((total, item) => total + basePremiumOf(item), 0);
  return roundInOfficesFavour(
    policyBasePremium + policyWideSurchargeOn(policyBasePremium) + PROCESSING_FEE,
  );
}
EOF
